    /// object (systemCode, type, url, subcommittees) is stored unchanged.
    nonisolated struct ProcessedBillCommittee: Decodable {
        let name: String
        /// House, Senate or Joint.
        let chamber: String
        /// The committee's own activities. Absent when only its subcommittees acted (Congress.gov then lists the
        /// activities under subcommittees, as on H.R. 471 of the 119th Congress).
        let activities: [ProcessedBillCommitteeActivity]?
    }

    nonisolated struct ProcessedBillCommitteeActivity: Decodable {
        /// Such as Referred to, Markup by or Reported by.
        let name: String
        /// Absent on some activities, such as Bills of Interest - Exchange of Letters (H.R. 3838 and H.R. 4275 of the
        /// 119th Congress).
        let date: String?
    }

    nonisolated struct OfficialVotesBreakdown: Decodable {
        let house: OfficialChamberVote?
        let senate: OfficialChamberVote?
        let lastSyncedAt: String
        let source: String
        let completeness: String
    }

    nonisolated struct OfficialChamberVote: Decodable {
        let yea: Int
        let nay: Int
        let present: Int
        let notVoting: Int
        let totalCounted: Int
        let actionCode: String?
        let actionDate: String?
        let resultText: String?
        let memberDataAvailable: Bool
        let members: [OfficialVoteMember]
    }

    nonisolated struct OfficialVoteMember: Decodable {
        let bioguideId: String
        let displayName: String
        let party: String?
        let state: String?
        let district: String?
        let votePosition: String
    }
}

// For fields whose schema allows a string or an integer. The first attempt uses try? because decoding a
// number as a String (or a string as an Int) throws typeMismatch; any other type still throws from the second.
nonisolated private extension KeyedDecodingContainer {
    func decodeStringOrIntIfPresent(forKey key: Key) throws -> String? {
        if let stringValue = try? decodeIfPresent(String.self, forKey: key) {
            return stringValue
        }
        if let intValue = try decodeIfPresent(Int.self, forKey: key) {
            return String(intValue)
        }
        return nil
    }

    func decodeIntIfPresent(forKey key: Key) throws -> Int? {
        if let intValue = try? decodeIfPresent(Int.self, forKey: key) {
            return intValue
        }
        if let stringValue = try decodeIfPresent(String.self, forKey: key) {
            return Int(stringValue)
        }
        return nil
    }
}
